;#############################################################################################################
;# yi/SuperFX/Banks/Bank4C.asm -- SuperFX data bank $4C ($4C:0000-$4C:FFFF, 64 KB).
;#
;# Notable interior addresses (observed):
;#   $4C:32A4 -- Map16 page-table OFFSET table (167 entries, dw each, relative
;#               to the data base at $4C:33F2). One offset per Map16 page (~$00..$A6).
;#   $4C:33F2 -- Map16 page-table DATA. Each page is a contiguous run of
;#               8-byte/4-word chunks; each chunk is one 16x16 BG tile encoded
;#               as 4 sub-tile words (YXPP CCCV VVVV VVVV: Y/X flip, palette,
;#               VRAM tile index). Region extent: $4C:33F2 .. $4C:D619 (~41 KB).
;#               Consumed by the SNES Map16 walker (Bank12 fetch primitives;
;#               see docs/leveldataengine.md S3.5) and by SuperFX BG-stamp code.
;# Bank4C is HiROM-mirrored: SNES bank $4C maps to the same 64 KB block
;# that LoROM banks $18-$19 cover -- this is YI's "shared space" used by
;# both the 65816 (via HiROM mapping) and the SuperFX (via native bank
;# addressing). External references (e.g. SMW Central's memory map) cite
;# the page-table base at LoROM `$18:B3F2` -- same byte as `$4C:33F2`
;# here, just viewed through the LoROM mapping.
;# CORRECTION TO EXTERNAL REFS: SMW Central states the page-table region
;# ends at `$1A:D619` (74 KB total). That overstates by ~33 KB: the actual
;# region ends at `$4C:D619` (~41 KB / 167 pages). The bytes from
;# `$4C:D61A` through `$4D:5619` are DIFFERENT structures (SuperFX graphics
;# descriptor table at $4CD61A + enemy-data pointer table at $4D:0000, see
;# yi/SuperFX/Banks/Bank4D.asm header).
;#
;# Most of Bank4C is data (graphic asset tables, SuperFX-side decompressed
;# bitmaps, enemy character pointer tables) rather than executable code.
;# A small block of SuperFX program code lives near the end of the bank
;# (see entries in RoutinePointers.asm pointing at CODE_4Cxxxx labels).
;#
;# Contents at a glance:
;#   $4C:0000 DATA_extended_object_mode_table  -- 512+ bytes of mostly $06 values, looks
;#                                            like an animation-timing or pose-table
;#                                            for extended objects (one entry per
;#                                            enemy state). Consumed by the engine's
;#                                            extended-object mode loaders.
;#   $4C:060C bg_unit_data_addr_table     -- (earlier pointer table; semantics TBD,
;#                                            distinct from the $4C:32A4 Map16 offset table)
;#   $4C:32A4 map16_page_offset_table     -- 167 dw entries, offsets into the data block.
;#   $4C:33F2 map16_page_data             -- Map16 page-table DATA (see Notable above).
;#   $4C:D61A DATA_4CD61A                 -- SuperFX BG-stamp graphics descriptor table
;#                                            (`db count : dw vram_dest : 32 dw sub-tiles`,
;#                                            ~74 entries, $00-terminated). NOT Map16 data.
;#
;# See also:
;#   chip/ys_chip0.asm through chip/ys_chip7.asm  -- chip program files whose data-driving
;#                                                   routines consume these tables
;#   chip/Gdefchr.asm                             -- global character defs
;#
;# Cross-references:
;#   yi/SuperFX/RoutinePointers.asm                  -- pointer-table entries pointing into 4C
;#   docs/mchip.md                          -- standalone SuperFX reference
;#############################################################################################################

%SuperFXBankStart(!FXBank4C)

